-- Matt, 16 Nov: every high-value benefit (call-out waivers, repair discounts,
-- inspections, CP12) is available after the third payment, like the annual
-- service. Data-only; the seed sets the same text for fresh databases.
UPDATE "ClauseTemplate" SET "bodyText" = 'One scheduled service of your gas fire in each 12-month plan period, including the manufacturer''s recommended safety checks. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'GAS_FIRE_SERVICE';
UPDATE "ClauseTemplate" SET "bodyText" = 'One safety check of your gas cooker or hob in each 12-month plan period, carried out alongside your annual service where practical. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'COOKER_HOB_CHECK';
UPDATE "ClauseTemplate" SET "bodyText" = 'One scheduled service of your unvented hot water cylinder in each 12-month plan period, including the discharge and safety device checks required by the manufacturer. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'UNVENTED_CYLINDER';
UPDATE "ClauseTemplate" SET "bodyText" = 'A check of your central heating system alongside your annual service: system pressure, flow and return temperatures, and thermostatic radiator valve operation. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'HEALTH_CHECK';
UPDATE "ClauseTemplate" SET "bodyText" = 'A legionella risk assessment of the hot and cold water system, with a written record for your compliance file. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'LEGIONELLA';
UPDATE "ClauseTemplate" SET "bodyText" = 'A 15% discount applies to our standard labour rates for work arising from visits made under this plan. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'LABOUR_DISCOUNT_15';
UPDATE "ClauseTemplate" SET "bodyText" = 'A 10% discount applies to parts supplied by us for work carried out under this plan. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'PARTS_DISCOUNT';
UPDATE "ClauseTemplate" SET "bodyText" = 'Our standard diagnostic charge is not applied to plan members. Any remedial work identified remains chargeable at your plan rates. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment', "engineerNote" = 'available after the customer''s 3rd payment' WHERE "code" = 'DIAGNOSTIC_WAIVED';
UPDATE "ClauseTemplate" SET "bodyText" = 'When we attend a visit you request under this plan, our usual attendance charge is waived. This is not a promise to attend at any particular time. Labour and parts for any work carried out remain chargeable at the rates shown in your plan. This benefit is available once your third monthly payment has been collected.', "note" = 'available after your third payment; your attendance charge is waived when we attend', "engineerNote" = 'available after the customer''s 3rd payment; their attendance charge is waived when you attend' WHERE "code" = 'NO_CALLOUT_FEE';
